using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_WhenNoNotifications_ReturnsSuccessWithEmptyList()
        {
            // Drain any pre-existing notifications
            JsonResult drainResult;
            do
            {
                drainResult = _controller.GetNotifications();
            } while (GetNotificationCount(drainResult) > 0);

            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            dynamic? value = result.Value;
            Assert.NotNull(value);
            // Check it's a success response
            var valueType = value!.GetType();
            var successProp = valueType.GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value));
            var countProp = valueType.GetProperty("count");
            Assert.Equal(0, (int)countProp!.GetValue(value));
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            var valueType = result.Value!.GetType();
            var successProp = valueType.GetProperty("success");
            Assert.True((bool)successProp!.GetValue(result.Value));
        }

        private int GetNotificationCount(JsonResult result)
        {
            if (result.Value == null) return 0;
            var valueType = result.Value.GetType();
            var countProp = valueType.GetProperty("count");
            if (countProp == null) return 0;
            return (int)countProp.GetValue(result.Value)!;
        }
    }
}

