using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextHelper.CreateContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void DbSets_AreAvailable()
        {
            Assert.NotNull(_context.Courses);
            Assert.NotNull(_context.Students);
            Assert.NotNull(_context.Instructors);
            Assert.NotNull(_context.Departments);
            Assert.NotNull(_context.Enrollments);
            Assert.NotNull(_context.OfficeAssignments);
            Assert.NotNull(_context.CourseAssignments);
            Assert.NotNull(_context.Notifications);
            Assert.NotNull(_context.People);
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.Parse("2020-01-01")
            };

            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.FirstOrDefault(s => s.LastName == "User");
            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(DateTime.Parse("2020-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Prof",
                LastName = "Smith",
                HireDate = DateTime.Parse("2015-06-15")
            };

            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.FirstOrDefault(i => i.LastName == "Smith");
            Assert.NotNull(retrieved);
            Assert.Equal("Prof", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            var dept = new Department
            {
                Name = "Test Dept",
                Budget = 10000,
                StartDate = DateTime.Parse("2020-01-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 5000,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Find(5000);
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            var dept = new Department
            {
                Name = "Physics",
                Budget = 250000,
                StartDate = DateTime.Parse("2020-09-01")
            };

            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.FirstOrDefault(d => d.Name == "Physics");
            Assert.NotNull(retrieved);
            Assert.Equal(250000, retrieved.Budget);
        }

        [Fact]
        public void CanAddEnrollment()
        {
            var student = new Student
            {
                FirstMidName = "A",
                LastName = "B",
                EnrollmentDate = DateTime.Now
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "D",
                Budget = 1,
                StartDate = DateTime.Now
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 9000,
                Title = "C",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = 9000,
                Grade = Grade.A
            };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments.FirstOrDefault(e => e.StudentID == student.ID && e.CourseID == 9000);
            Assert.NotNull(retrieved);
            Assert.Equal(Grade.A, retrieved.Grade);
        }

        [Fact]
        public void CourseAssignment_CompositeKey_Works()
        {
            var instructor = new Instructor
            {
                FirstMidName = "I",
                LastName = "J",
                HireDate = DateTime.Now
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "K",
                Budget = 1,
                StartDate = DateTime.Now
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 9001,
                Title = "L",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment
            {
                CourseID = 9001,
                InstructorID = instructor.ID
            };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(9001, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void OfficeAssignment_OneToOne_Works()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Test",
                HireDate = DateTime.Now
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 101"
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Room 101", retrieved.Location);
        }

        [Fact]
        public void CanAddNotification()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };

            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.FirstOrDefault(n => n.Message == "Test notification");
            Assert.NotNull(retrieved);
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("CREATE", retrieved.Operation);
        }

        [Fact]
        public void Person_FullName_ReturnsCombinedName()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Smith",
                EnrollmentDate = DateTime.Now
            };

            Assert.Equal("Smith, John", student.FullName);
        }

        [Fact]
        public void Student_InheritsPerson()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Inherit",
                EnrollmentDate = DateTime.Now
            };

            Assert.IsAssignableFrom<Person>(student);
        }

        [Fact]
        public void Instructor_InheritsPerson()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Inherit",
                HireDate = DateTime.Now
            };

            Assert.IsAssignableFrom<Person>(instructor);
        }
    }
}

